import{_ as e,o as t,c as d,a2 as n}from"./chunks/framework.D0_YsCyK.js";const u=JSON.parse('{"title":"O7 备份恢复功能全量审计","description":"","frontmatter":{},"headers":[],"relativePath":"audit/O7-backup.md","filePath":"audit/O7-backup.md","lastUpdated":1792449669000}'),r={name:"audit/O7-backup.md"};function a(i,o,s,c,l,p){return t(),d("div",null,[...o[0]||(o[0]=[n('<h1 id="o7-备份恢复功能全量审计" tabindex="-1">O7 备份恢复功能全量审计 <a class="header-anchor" href="#o7-备份恢复功能全量审计" aria-label="Permalink to &quot;O7 备份恢复功能全量审计&quot;">​</a></h1><p><strong>审计时间</strong>：2026-10-20 <strong>审计范围</strong>：备份导出、备份导入、字段完整性、文件安全、定时备份 <strong>结论</strong>：发现 P1×5 / P2×5 / P3×3，无 P0</p><hr><h2 id="p1-严重-恢复后数据丢失" tabindex="-1">P1 严重（恢复后数据丢失） <a class="header-anchor" href="#p1-严重-恢复后数据丢失" aria-label="Permalink to &quot;P1 严重（恢复后数据丢失）&quot;">​</a></h2><h3 id="o7-001-user-inbound-表完全未备份-—-订阅分配关系丢失" tabindex="-1">O7-001：<code>user_inbound</code> 表完全未备份 — 订阅分配关系丢失 <a class="header-anchor" href="#o7-001-user-inbound-表完全未备份-—-订阅分配关系丢失" aria-label="Permalink to &quot;O7-001：`user_inbound` 表完全未备份 — 订阅分配关系丢失&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/model/model.go:444</code> (<code>BackupData</code> 无 <code>UserInbounds</code> 字段)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:1982</code> (<code>ExportAll</code> 未导出 <code>user_inbound</code> 表)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2431</code> (<code>Import</code> 未恢复该表)</li><li><strong>影响</strong>：<code>user_inbound</code> 是订阅分配关系表（哪个用户可访问哪个入站/中转）。全量备份恢复后，所有用户的订阅分配关系<strong>全部丢失</strong>，用户将看不到任何订阅节点。</li><li><strong>复现</strong>：导出备份 → 清空 <code>user_inbound</code> 表 → 导入备份 → 分配关系未恢复。</li><li><strong>证据</strong>：<code>BackupData</code> 结构体包含 users/nodes/tunnels/forwards/userTunnels/speedLimits/tunnelGroups/userGroups/permissions/configs/inbounds，但无 userInbounds。</li></ul><h3 id="o7-002-chaintunnelbackup-缺-connectip-—-链式隧道连接-ip-丢失" tabindex="-1">O7-002：<code>ChainTunnelBackup</code> 缺 <code>ConnectIP</code> — 链式隧道连接 IP 丢失 <a class="header-anchor" href="#o7-002-chaintunnelbackup-缺-connectip-—-链式隧道连接-ip-丢失" aria-label="Permalink to &quot;O7-002：`ChainTunnelBackup` 缺 `ConnectIP` — 链式隧道连接 IP 丢失&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/model/model.go:646</code> (<code>ChainTunnelBackup</code> 无 <code>ConnectIP</code> 字段)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2252</code> (<code>exportChainTunnels</code> 未导出 <code>ConnectIP</code>)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2699</code> (<code>importTunnels</code> 中 ChainTunnel 恢复未设置 <code>ConnectIP</code>，更新列也不含 <code>connect_ip</code>)</li><li><strong>影响</strong>：<code>ChainTunnel.ConnectIP</code> 用于链式隧道探测和连接（<code>tunnel_best_exit.go:163</code>、<code>tunnel_quality_prober.go:392,583</code>）。恢复后链式隧道的多跳连接 IP 丢失，可能导致链式转发失败。</li><li><strong>对照</strong>：<code>ChainTunnel</code> 模型有 9 个字段（ID/TunnelID/ChainType/NodeID/Port/Strategy/Inx/Protocol/ConnectIP），备份只覆盖 8 个。</li></ul><h3 id="o7-003-userbackup-缺-passwordchangedat-和-maxconn" tabindex="-1">O7-003：<code>UserBackup</code> 缺 <code>PasswordChangedAt</code> 和 <code>MaxConn</code> <a class="header-anchor" href="#o7-003-userbackup-缺-passwordchangedat-和-maxconn" aria-label="Permalink to &quot;O7-003：`UserBackup` 缺 `PasswordChangedAt` 和 `MaxConn`&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2141</code> (<code>exportUsers</code> 未导出 <code>u.PasswordChangedAt</code> 和 <code>u.MaxConn</code>)</li><li><strong>影响</strong>： <ul><li><code>PasswordChangedAt</code> 丢失：影响强制改密逻辑判断（M-05 功能）。恢复后用户可能被错误要求改密，或绕过改密要求。</li><li><code>MaxConn</code> 丢失：用户连接数限制恢复后变为 0（无限制），限流策略失效。</li></ul></li><li><strong>对照</strong>：<code>User</code> 模型有 16 个字段，<code>UserBackup</code> 只覆盖 14 个（缺上述 2 个）。此问题在 I-database-reaudit 中已报告为 P2-2，此处确认仍未修复。</li></ul><h3 id="o7-004-forwardbackup-缺-maxconn-—-转发连接数限制丢失" tabindex="-1">O7-004：<code>ForwardBackup</code> 缺 <code>MaxConn</code> — 转发连接数限制丢失 <a class="header-anchor" href="#o7-004-forwardbackup-缺-maxconn-—-转发连接数限制丢失" aria-label="Permalink to &quot;O7-004：`ForwardBackup` 缺 `MaxConn` — 转发连接数限制丢失&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2279</code> (<code>exportForwards</code> 未导出 <code>f.MaxConn</code>)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2739</code> (<code>importForwards</code> 未恢复 <code>MaxConn</code>，更新列也不含 <code>max_conn</code>)</li><li><strong>影响</strong>：恢复后转发的 <code>MaxConn</code> 连接数限制丢失（变为 0=无限制），可能导致单转发耗尽服务器连接数。</li><li><strong>对照</strong>：<code>Forward</code> 模型有 20 个字段，<code>ForwardBackup</code> 覆盖 19 个（缺 <code>MaxConn</code>）。<code>IPMaxConn</code> 已覆盖，唯独 <code>MaxConn</code> 遗漏。此问题在 I-database-reaudit 中已报告为 P2-1，此处确认仍未修复。</li></ul><h3 id="o7-005-forwardportbackup-缺-inip-—-端口入口-ip-丢失" tabindex="-1">O7-005：<code>ForwardPortBackup</code> 缺 <code>InIP</code> — 端口入口 IP 丢失 <a class="header-anchor" href="#o7-005-forwardportbackup-缺-inip-—-端口入口-ip-丢失" aria-label="Permalink to &quot;O7-005：`ForwardPortBackup` 缺 `InIP` — 端口入口 IP 丢失&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/model/model.go:680</code> (<code>ForwardPortBackup</code> 只有 NodeID/Port，无 InIP)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2315</code> (<code>exportForwardPorts</code> 未导出 <code>fp.InIP</code>)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:2772</code> (<code>importForwards</code> 创建 ForwardPort 时未设置 <code>InIP</code>：<code>tx.Create(&amp;model.ForwardPort{ForwardID: f.ID, NodeID: fp.NodeID, Port: fp.Port})</code>)</li><li><strong>影响</strong>：<code>ForwardPort.InIP</code> 用于 nftables 绑定（<code>nftables_runtime.go:225</code>：<code>BindIP: strings.TrimSpace(fp.InIP)</code>）和端口冲突检测。恢复后多 IP 服务器的端口绑定 IP 丢失，可能导致转发监听错误的网卡。</li><li><strong>对照</strong>：<code>ForwardPort</code> 模型有 5 个字段（ID/ForwardID/NodeID/Port/InIP），备份只覆盖 2 个（NodeID/Port）。ID 和 ForwardID 可重建，但 InIP 是业务数据不应丢失。</li></ul><hr><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="o7-006-nodebackup-缺-expiryreminderdismissed-—-到期提醒重现" tabindex="-1">O7-006：<code>NodeBackup</code> 缺 <code>ExpiryReminderDismissed</code> — 到期提醒重现 <a class="header-anchor" href="#o7-006-nodebackup-缺-expiryreminderdismissed-—-到期提醒重现" aria-label="Permalink to &quot;O7-006：`NodeBackup` 缺 `ExpiryReminderDismissed` — 到期提醒重现&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/model/model.go:597</code> (<code>NodeBackup</code> 无该字段)</li><li><strong>影响</strong>：恢复后用户已忽略的节点到期提醒会重新弹出。低危害，但属于数据不一致。</li><li><strong>备注</strong>：在 I-database-reaudit 中已报告为 P2-3，此处确认仍未修复。</li></ul><h3 id="o7-007-announcement-表未备份" tabindex="-1">O7-007：<code>announcement</code> 表未备份 <a class="header-anchor" href="#o7-007-announcement-表未备份" aria-label="Permalink to &quot;O7-007：`announcement` 表未备份&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:1982</code> (<code>ExportAll</code> 未导出 <code>announcement</code> 表)</li><li><strong>影响</strong>：全量备份恢复后，系统公告丢失。需管理员重新发布。</li></ul><h3 id="o7-008-monitor-permission-表未备份" tabindex="-1">O7-008：<code>monitor_permission</code> 表未备份 <a class="header-anchor" href="#o7-008-monitor-permission-表未备份" aria-label="Permalink to &quot;O7-008：`monitor_permission` 表未备份&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:1982</code> (<code>ExportAll</code> 未导出 <code>monitor_permission</code> 表)</li><li><strong>影响</strong>：非管理员用户的监控权限在恢复后丢失，需重新授权。</li></ul><h3 id="o7-009-备份版本无兼容性检查" tabindex="-1">O7-009：备份版本无兼容性检查 <a class="header-anchor" href="#o7-009-备份版本无兼容性检查" aria-label="Permalink to &quot;O7-009：备份版本无兼容性检查&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/handler.go:1787</code> (<code>backupImport</code> 只检查 <code>req.BackupData.Version == &quot;&quot;</code>，不验证版本号)</li><li><strong>文件</strong>：<code>go-backend/internal/store/repo/repository.go:1983</code> (导出时硬编码 <code>Version: &quot;1.0&quot;</code>)</li><li><strong>影响</strong>：未来版本新增字段时，旧版备份导入新版会静默丢失新字段数据；新版备份导入旧版可能因未知字段失败。应实现版本协商或迁移逻辑。</li></ul><h3 id="o7-010-导入前自动备份失败会中断恢复" tabindex="-1">O7-010：导入前自动备份失败会中断恢复 <a class="header-anchor" href="#o7-010-导入前自动备份失败会中断恢复" aria-label="Permalink to &quot;O7-010：导入前自动备份失败会中断恢复&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/handler.go:1783-1787</code></li></ul><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">autoBackup, err </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> h.repo.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ExportAll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> err </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    response.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WriteJSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(w, response.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Err</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, fmt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Sprintf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;导入前自动备份失败: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, err)))</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><strong>影响</strong>：如果当前数据库已损坏（<code>ExportAll</code> 失败），用户无法从完好备份恢复——而这正是恢复功能最该工作的场景。建议：自动备份失败时警告但允许继续（用户已明确要覆盖）。</li></ul><hr><h2 id="p3-备注" tabindex="-1">P3 备注 <a class="header-anchor" href="#p3-备注" aria-label="Permalink to &quot;P3 备注&quot;">​</a></h2><h3 id="o7-011-无定时自动备份功能" tabindex="-1">O7-011：无定时自动备份功能 <a class="header-anchor" href="#o7-011-无定时自动备份功能" aria-label="Permalink to &quot;O7-011：无定时自动备份功能&quot;">​</a></h3><ul><li><strong>现状</strong>：只有手动导出（<code>/api/v1/backup/export</code>），无定时任务。</li><li><strong>建议</strong>：增加每日自动备份到本地目录，保留 N 天。属功能增强，非缺陷。</li></ul><h3 id="o7-012-federation-tunnel-binding-未备份" tabindex="-1">O7-012：<code>federation_tunnel_binding</code> 未备份 <a class="header-anchor" href="#o7-012-federation-tunnel-binding-未备份" aria-label="Permalink to &quot;O7-012：`federation_tunnel_binding` 未备份&quot;">​</a></h3><ul><li><strong>影响</strong>：联邦隧道绑定关系在恢复后丢失。可能是有意设计（联邦配置通常不随备份迁移），记录备查。</li></ul><h3 id="o7-013-subscriptionbackup-缺-updatedtime" tabindex="-1">O7-013：<code>SubscriptionBackup</code> 缺 <code>UpdatedTime</code> <a class="header-anchor" href="#o7-013-subscriptionbackup-缺-updatedtime" aria-label="Permalink to &quot;O7-013：`SubscriptionBackup` 缺 `UpdatedTime`&quot;">​</a></h3><ul><li><strong>影响</strong>：极小。<code>UpdatedTime</code> 仅用于显示，恢复后会被重置为导入时间。可忽略。</li></ul><hr><h2 id="已验证通过" tabindex="-1">已验证通过 <a class="header-anchor" href="#已验证通过" aria-label="Permalink to &quot;已验证通过&quot;">​</a></h2><ol><li><strong>备份文件大小限制</strong>：导入用 <code>decodeJSONWithLimit(r.Body, &amp;req, 100&lt;&lt;20)</code>，100MB 上限（<code>handler.go:1770</code>）。AUDIT-R22 已验证合理。</li><li><strong>导出 buffer-first</strong>：先 Encode 到 buffer 再写响应，防止截断损坏（<code>handler.go:1737-1748</code>，LAD22-001）。</li><li><strong>导入事务性</strong>：<code>Import</code> 在 <code>r.db.Transaction</code> 中执行，任一表失败则整体回滚（<code>repository.go:2436</code>）。</li><li><strong>TunnelBackup 字段完整</strong>：14 个字段全覆盖 ✓</li><li><strong>UserTunnelBackup 字段完整</strong>：12 个字段全覆盖 ✓</li><li><strong>SpeedLimitBackup 字段完整</strong>：8 个字段全覆盖 ✓</li><li><strong>TunnelGroup/UserGroup/Permission 字段完整</strong> ✓</li><li><strong>SubscriptionBackup 核心字段完整</strong>：Options 存原始 JSON，新字段自动保留 ✓</li></ol><hr><h2 id="字段对照总表" tabindex="-1">字段对照总表 <a class="header-anchor" href="#字段对照总表" aria-label="Permalink to &quot;字段对照总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>字段数</th><th>备份覆盖</th><th>缺失字段</th><th>级别</th></tr></thead><tbody><tr><td>User</td><td>16</td><td>14</td><td>PasswordChangedAt, MaxConn</td><td>P1</td></tr><tr><td>Node</td><td>29</td><td>28</td><td>ExpiryReminderDismissed</td><td>P2</td></tr><tr><td>Tunnel</td><td>14</td><td>14</td><td>—</td><td>✓</td></tr><tr><td>Forward</td><td>20</td><td>19</td><td>MaxConn</td><td>P1</td></tr><tr><td>ForwardPort</td><td>5</td><td>2</td><td>InIP (ID/ForwardID可重建)</td><td>P1</td></tr><tr><td>ChainTunnel</td><td>9</td><td>8</td><td>ConnectIP</td><td>P1</td></tr><tr><td>UserTunnel</td><td>12</td><td>12</td><td>—</td><td>✓</td></tr><tr><td>SpeedLimit</td><td>8</td><td>8</td><td>—</td><td>✓</td></tr><tr><td>TunnelGroup</td><td>5</td><td>5</td><td>—</td><td>✓</td></tr><tr><td>UserGroup</td><td>5</td><td>5</td><td>—</td><td>✓</td></tr><tr><td>GroupPermission</td><td>5</td><td>5</td><td>—</td><td>✓</td></tr><tr><td>GroupPermissionGrant</td><td>6</td><td>6</td><td>—</td><td>✓</td></tr><tr><td>Subscription</td><td>22</td><td>20</td><td>AppliedActive(运行时), UpdatedTime</td><td>P3</td></tr><tr><td>UserInbound</td><td>4</td><td>0</td><td><strong>整表未备份</strong></td><td>P1</td></tr><tr><td>Announcement</td><td>4</td><td>0</td><td>整表未备份</td><td>P2</td></tr><tr><td>MonitorPermission</td><td>4</td><td>0</td><td>整表未备份</td><td>P2</td></tr></tbody></table><hr><h2 id="建议修复顺序" tabindex="-1">建议修复顺序 <a class="header-anchor" href="#建议修复顺序" aria-label="Permalink to &quot;建议修复顺序&quot;">​</a></h2><ol><li><strong>O7-001</strong>（P1）：<code>BackupData</code> 加 <code>UserInbounds</code> 字段 + 导出/导入（影响最大：订阅分配全丢）</li><li><strong>O7-002</strong>（P1）：<code>ChainTunnelBackup</code> 加 <code>ConnectIP</code></li><li><strong>O7-003</strong>（P1）：<code>exportUsers</code> 加 <code>PasswordChangedAt</code>/<code>MaxConn</code></li><li><strong>O7-004</strong>（P1）：<code>exportForwards</code>/<code>importForwards</code> 加 <code>MaxConn</code></li><li><strong>O7-005</strong>（P1）：<code>ForwardPortBackup</code> 加 <code>InIP</code></li><li><strong>O7-010</strong>（P2）：自动备份失败时允许继续导入（加警告）</li><li>其余 P2/P3 按需处理</li></ol><p><strong>只审计未修复</strong>：源代码未修改。</p>',46)])])}const g=e(r,[["render",a]]);export{u as __pageData,g as default};
